#!/usr/bin/env bash
# SPDX-License-Identifier: MPL-2.0
#
# actions.lock consistency guard.
#
# `.github/workflows/actions.lock` (GitHub's actions lockfile, generated by
# `gh actions-lock`) is this repo's pin authority: it maps every action a
# workflow uses to a commit SHA. GitHub refuses to start a workflow whose
# `uses:` refs do not match the lock, and reports only a `startup_failure`
# with zero jobs. That is how the `CI` workflow stopped running on every
# push and PR from 2026-10-11: Dependabot (#782) bumped
# `actions/setup-node` and `actions/upload-artifact` in ci.yml without
# regenerating the lock.
#
# For each workflow, this check compares the set of external actions its
# `uses:` lines reference (sub-path actions such as
# `github/codeql-action/init@v4` count as `github/codeql-action@v4`; local
# `./` actions, `docker://` images and reusable workflows (a job-level
# `uses:` naming a `.github/workflows/*.yml` file) are not locked)
# with the set the lock lists for it, and fails on any difference, either
# way round. It also fails if a locked action has no `dependencies:` entry.
#
# Usage: tools/ci/check-actions-lock.sh [WORKFLOW_DIR]   (default .github/workflows)
set -uo pipefail

dir="${1:-.github/workflows}"
lock="$dir/actions.lock"
fail=0
err() { printf '::error::%s\n' "$*"; fail=1; }

[[ -f "$lock" ]] || { err "actions lockfile missing: $lock"; exit 1; }

# Split a workflow (comments stripped) by context: lines inside a `steps:`
# block (more indented than its `steps:` key) are tagged S, all others J.
# A reusable workflow is called by a job (`jobs.<id>.uses`), never by a step,
# so the reusable-workflow exclusion below applies to J lines only: a step
# action whose directory happens to be named `.github/workflows/x.yml` is
# still checked.
tag() {
  sed -E 's/[[:space:]]+#.*$//' "$1" | awk '
    { match($0, /^ */); ind = RLENGTH }
    /^[[:space:]]*$/ { next }
    in_steps && ind <= sind { in_steps = 0 }
    /^[[:space:]]*["'\'']?steps["'\'']?[[:space:]]*:/ {
      # `steps: [{uses: …}]` (flow sequence on the key line) is step context too.
      print (match($0, /:[[:space:]]*[^[:space:]]/) ? "S" : "J") "\t" $0
      in_steps = 1; sind = ind; next
    }
    { print (in_steps ? "S" : "J") "\t" $0 }
  '
}

# The `uses:` values on lines tagged $2 (S or J), action-shaped only.
# Block style (`- uses: x`), flow style (`- {uses: x, with: …}`) and quoted keys (`"uses": x`).
# Only action-shaped values count (`owner/repo[/path]@ref`, a ref may hold `/`), so `uses:` text in
# a `run:` script (a grep pattern, say) is not mistaken for a step.
refs() {
  tag "$1" | grep -E "^$2"$'\t' | cut -f2- \
    | grep -oE '(^|[{,[:space:]-])["'\'']?uses["'\'']?[[:space:]]*:[[:space:]]*[^[:space:],}]+' \
    | sed -E 's/^.*uses["'\'']?[[:space:]]*:[[:space:]]*//; s/^["'\'']//; s/["'\'']$//' \
    | grep -vE '^(\./|docker://)' \
    | grep -E '^[A-Za-z0-9_.-]+/[A-Za-z0-9_./-]+@[A-Za-z0-9_./-]+$'
}

# The actions a workflow file uses, normalised and sorted.
used() {
  local file="$1"
  { refs "$file" S; refs "$file" J | grep -vE '/\.github/workflows/[^/@]+\.ya?ml@'; } \
    | sed -E 's#^([^/@]+/[^/@]+)/[^@]*@#\1@#' \
    | sort -u
}

# Fail closed: a `uses:` key at the start of a line (block `uses:` / `- uses:`,
# or a flow mapping opened on the line, `- {uses: …}`) whose value the matcher
# above cannot read is an error, not a silent skip. That covers folded or
# literal scalars (`uses: >-` with the ref on the next line), an empty value,
# and anything else that is not a local action (`./…`), a Docker image
# (`docker://…`), a reusable workflow (`owner/repo/.github/workflows/x.yml@ref`)
# or an action (`owner/repo[/path]@ref`). Write such a step as a plain scalar.
unreadable() {
  local file="$1"
  sed -E 's/[[:space:]]+#.*$//' "$file" \
    | grep -nE '^[[:space:]]*(-[[:space:]]+)?\{?[[:space:]]*["'\'']?uses["'\'']?[[:space:]]*:' \
    | while IFS= read -r line; do
        local n="${line%%:*}" v
        v=$(printf '%s\n' "${line#*:}" \
          | sed -E 's/^[[:space:]]*(-[[:space:]]+)?\{?[[:space:]]*["'\'']?uses["'\'']?[[:space:]]*:[[:space:]]*//; s/[[:space:]]*[,}].*$//; s/^["'\'']//; s/["'\'']$//')
        if ! printf '%s\n' "$v" | grep -qE '^(\./|docker://|[A-Za-z0-9_.-]+/[A-Za-z0-9_./-]+@[A-Za-z0-9_./-]+$)'; then
          printf '%s: %s\n' "$n" "${v:-<empty>}"
        fi
      done
}

# The actions the lock lists for workflow path $1, sorted.
locked() {
  local path="$1"
  awk -v wf="'$path':" '
    /^workflows:/ { inwf = 1; next }
    /^dependencies:/ { inwf = 0 }
    inwf && $1 == wf { on = 1; next }
    inwf && on && /^        - / { v = $2; gsub(/'\''/, "", v); print v; next }
    inwf && on { on = 0 }
  ' "$lock" | sort -u
}

# Dependency keys present in the lock.
deps=$(awk '/^dependencies:/ { d = 1; next } d && /^    '\''/ { k = $1; gsub(/['\'':]/, "", k); print k }' "$lock")

checked=0
for wf in "$dir"/*.yml "$dir"/*.yaml; do
  [[ -f "$wf" ]] || continue
  rel=".github/workflows/$(basename "$wf")"
  checked=$((checked + 1))
  bad=$(unreadable "$wf")
  [[ -z "$bad" ]] || err "$rel has uses: values this guard cannot read (write them as plain scalars): ${bad//$'\n'/; }"
  u=$(used "$wf")
  l=$(locked "$rel")
  if ! grep -qF "'$rel':" "$lock"; then
    [[ -z "$u" ]] || err "$rel uses actions but has no actions.lock entry: ${u//$'\n'/ }"
    continue
  fi
  missing=$(comm -23 <(printf '%s\n' "$u" | sed '/^$/d') <(printf '%s\n' "$l" | sed '/^$/d'))
  stale=$(comm -13 <(printf '%s\n' "$u" | sed '/^$/d') <(printf '%s\n' "$l" | sed '/^$/d'))
  [[ -z "$missing" ]] || err "$rel uses actions the lock does not list (regenerate actions.lock): ${missing//$'\n'/ }"
  [[ -z "$stale" ]] || err "$rel: actions.lock lists actions the workflow no longer uses: ${stale//$'\n'/ }"
  for a in $l; do
    printf '%s\n' "$deps" | grep -qxF "$a" || err "actions.lock has no dependencies entry for $a ($rel)"
  done
done

# Transitive references: an action the lock records may itself use other
# actions (`uses:` under its dependency record, e.g. upload-pages-artifact ->
# upload-artifact@<sha>). Each of those must have its own record too.
while IFS= read -r t; do
  [[ -n "$t" ]] || continue
  printf '%s\n' "$deps" | grep -qxF "$t" || err "actions.lock: a dependency uses $t, which has no dependencies entry"
done < <(awk '/^dependencies:/ { d = 1; next } d && /^        uses:/ { u = 1; next } d && u && /^            - / { v = $2; gsub(/'\''/, "", v); print v; next } { u = 0 }' "$lock" | sort -u)

if [[ "$fail" -ne 0 ]]; then
  echo "actions.lock check FAILED: a mismatched workflow does not start (startup_failure, zero jobs)."
  exit 1
fi
echo "actions.lock check: OK ($checked workflows match the lock)"
